import math


def minimum_network(node_count, links):
    if isinstance(node_count, bool) or not isinstance(node_count, int):
        raise TypeError("node_count must be an integer")
    if node_count < 1:
        raise ValueError("node_count must be positive")
    matrix = [[None] * node_count for _ in range(node_count)]
    for i in range(node_count):
        matrix[i][i] = 0
    edges = []
    for left, right, cost in links:
        if isinstance(left, bool) or isinstance(right, bool) or not isinstance(left, int) or not isinstance(right, int):
            raise TypeError("endpoints must be integers")
        if not 0 <= left < node_count or not 0 <= right < node_count:
            raise ValueError("endpoint out of range")
        if isinstance(cost, bool) or not isinstance(cost, (int, float)):
            raise TypeError("cost must be numeric")
        if cost < 0 or not math.isfinite(cost):
            raise ValueError("invalid cost")
        a, b = sorted((left, right))
        edges.append((cost, a, b))
        if left != right and (matrix[left][right] is None or cost < matrix[left][right]):
            matrix[left][right] = matrix[right][left] = cost
    parent = list(range(node_count))

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    selected = []
    total = 0
    for cost, left, right in sorted(edges, reverse=True):
        a, b = find(left), find(right)
        if a != b:
            parent[a] = b
            selected.append((left, right, cost))
            total += cost
    if len(selected) != node_count - 1:
        raise ValueError("graph is disconnected")
    return matrix, selected, total
